CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY,email TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,last_seen_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS evaluation_runs (id TEXT PRIMARY KEY,user_id TEXT,name TEXT NOT NULL,scenario TEXT NOT NULL,model TEXT NOT NULL,status TEXT NOT NULL,total_cases INTEGER NOT NULL DEFAULT 0,passed_cases INTEGER NOT NULL DEFAULT 0,pass_rate REAL,p95_latency_ms REAL,input_tokens INTEGER NOT NULL DEFAULT 0,output_tokens INTEGER NOT NULL DEFAULT 0,estimated_cost_usd REAL NOT NULL DEFAULT 0,error_message TEXT,is_demo INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,completed_at TEXT,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS evaluation_cases (id TEXT PRIMARY KEY,run_id TEXT NOT NULL,case_name TEXT NOT NULL,input_text TEXT NOT NULL,output_text TEXT,expected_json TEXT NOT NULL,matched_json TEXT,passed INTEGER NOT NULL DEFAULT 0,score REAL NOT NULL DEFAULT 0,latency_ms REAL,input_tokens INTEGER NOT NULL DEFAULT 0,output_tokens INTEGER NOT NULL DEFAULT 0,error_message TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(run_id) REFERENCES evaluation_runs(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS request_metrics (id INTEGER PRIMARY KEY AUTOINCREMENT,path TEXT NOT NULL,method TEXT NOT NULL,status_code INTEGER NOT NULL,duration_ms REAL NOT NULL,user_id TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_runs_created ON evaluation_runs(created_at DESC);
CREATE INDEX IF NOT EXISTS idx_cases_run ON evaluation_cases(run_id);
CREATE INDEX IF NOT EXISTS idx_metrics_created ON request_metrics(created_at DESC);
